func tableJsonMapInteger(text []byte, f *TableFieldInfo) (uint64, bool) {
	var report TableReport
	in := tableJsonIn{text: text, report: &report}
	integral, ok := in.walkNumber()
	if !ok || in.pos != len(text) {
		return 0, false
	}
	_ = integral
	v, ok := tableJsonDecimalKey(text, f.Kind >= 2 && f.Kind <= 5, int(f.ElemSize)*8)
	return v, ok
}

// Decimal normalization preserves every uint64 bit and accepts integral
// exponent/fraction spellings without a binary floating-point conversion.
func tableJsonDecimalKey(text []byte, signed bool, width int) (uint64, bool) {
	i := 0
	negative := false
	if len(text) > 0 && text[0] == '-' {
		negative = true
		i++
	}
	var digits [tableJsonMaxNumber]byte
	n, fraction := 0, 0
	point := false
	for i < len(text) && text[i] != 'e' && text[i] != 'E' {
		c := text[i]
		i++
		if c == '.' {
			point = true
			continue
		}
		if n == len(digits) {
			return 0, false
		}
		digits[n] = c - '0'
		n++
		if point {
			fraction++
		}
	}
	exponent := 0
	if i < len(text) {
		i++
		minus := false
		if i < len(text) && (text[i] == '+' || text[i] == '-') {
			minus = text[i] == '-'
			i++
		}
		for i < len(text) {
			if exponent < 100000 {
				exponent = exponent*10 + int(text[i]-'0')
			}
			i++
		}
		if minus {
			exponent = -exponent
		}
	}
	first := 0
	for first < n && digits[first] == 0 {
		first++
	}
	if first == n {
		return 0, true
	}
	scale := exponent - fraction
	for scale < 0 && n > first && digits[n-1] == 0 {
		n--
		scale++
	}
	if scale < 0 || n-first+scale > 20 || negative && !signed {
		return 0, false
	}
	limit := ^uint64(0)
	if signed {
		limit = uint64(1) << uint(width-1)
		if !negative {
			limit--
		}
	} else if width < 64 {
		limit = uint64(1)<<uint(width) - 1
	}
	value := uint64(0)
	for j := first; j < n+scale; j++ {
		d := uint64(0)
		if j < n {
			d = uint64(digits[j])
		}
		if value > (limit-d)/10 {
			return 0, false
		}
		value = value*10 + d
	}
	if negative {
		value = -value
	}
	return value, true
}

func tableJsonWriteTimestamp(out *tableJsonOut, storage unsafe.Pointer) bool {
	var scratch [48]byte
	tableJsonWriteString(out, time.Unix(0, *(*int64)(storage)).UTC().AppendFormat(scratch[:0], time.RFC3339Nano))
	return true
}

func tableJsonReadTimestamp(in *tableJsonIn, storage unsafe.Pointer, f *TableFieldInfo) bool {
	var text [64]byte
	n, ok := in.scanString(text[:63])
	if !ok {
		return false
	}
	t, err := time.Parse(time.RFC3339Nano, string(text[:n]))
	// an instant outside Time.UnixNano's domain names no count and is refused too
	named := err == nil && !t.Before(time.Unix(0, -1<<63)) && !t.After(time.Unix(0, 1<<63-1))
	if !named {
		in.report.Reason = "timestamp_not_rfc3339: " + f.Name
		in.bad = true
		return false
	}
	*(*int64)(storage) = t.UnixNano()
	return true
}

// TableTimestampError is the refusal of a time.Time that no count names: its
// nanoseconds since the Unix epoch do not fit an int64, which is Time.UnixNano's
// own domain, the years 1678 through 2262 (mas-bandwidth/schema docs/SPEC-TABLES.md §2.11).
type TableTimestampError struct {
	Field string
	Time  time.Time
}

func (e TableTimestampError) Error() string {
	return "timestamp_out_of_range: " + e.Field + " " + e.Time.Format(time.RFC3339Nano) +
		" is outside the years 1678 through 2262, which a count of nanoseconds since the Unix epoch can hold"
}

// tableTimestampNanos is the count of a time.Time, and false for a time whose
// count UnixNano cannot represent. Go's zero Time{} is the zero time.
func tableTimestampNanos(t time.Time) (int64, bool) {
	if t.IsZero() {
		return 0, true
	}
	if t.Before(time.Unix(0, -1<<63)) || t.After(time.Unix(0, 1<<63-1)) {
		return 0, false
	}
	return t.UnixNano(), true
}

// tableTimestampTime is the UTC time of a count; every count is legal.
func tableTimestampTime(n int64) time.Time { return time.Unix(0, n).UTC() }

// tableJsonWriteTextElement writes one text-list element (mas-bandwidth/schema docs/SPEC-TABLES.md
// §2.13, §16.2): its string, or null for an absent ?string(M) element.
func tableJsonWriteTextElement(out *tableJsonOut, p unsafe.Pointer, f *TableFieldInfo) bool {
	v := &f.Table().Fields[0]
	if f.TextList == 2 && tableJsonGetRaw(unsafe.Add(p, uintptr(v.PresentOffset)), 1) == 0 {
		out.text("null")
		return true
	}
	if v.Unbounded {
		t, ok := tableTextBytes((*TableRef)(unsafe.Add(p, uintptr(v.Offset))), nil)
		if !ok {
			return false
		}
		tableJsonWriteString(out, t)
		return true
	}
	n := tableJsonCount(p, v)
	if n < 0 || n > v.ArrayBound {
		return false
	}
	tableJsonWriteString(out, tableJsonBytes(unsafe.Add(p, uintptr(v.Offset)), n))
	return true
}

// tableJsonReadTextElement reads one: a string, or null where the element may be
// absent; the caller's shape check has already counted every other JSON type.
func tableJsonReadTextElement(in *tableJsonIn, p unsafe.Pointer, f *TableFieldInfo, depth int32) bool {
	t := f.Table()
	t.Reset(p)
	if in.valueShape() == 'z' {
		return in.literal("null")
	}
	v := &t.Fields[0]
	if !tableJsonReadField(in, p, v, depth) {
		return false
	}
	if f.TextList == 2 {
		tableJsonSetRaw(unsafe.Add(p, uintptr(v.PresentOffset)), 1, 1)
	}
	return true
}

func tableJsonReadText(in *tableJsonIn, slot *TableRef) bool {
	*slot = 0
	probe := *in
	n, ok := probe.scanString(nil)
	if !ok {
		in.bad = true
		return false
	}
	if n == 0 {
		_, ok = in.scanString(nil)
		return ok
	}
	if in.graph == nil || in.graph.alloc == nil {
		in.bad = true
		return false
	}
	memory, ref := in.graph.alloc(9 + int64(n))
	if memory == nil {
		in.bad = true
		return false
	}
	*(*TableBlob)(memory) = TableBlob{Length: uint32(n)}
	if _, ok = in.scanString(unsafe.Slice((*byte)(unsafe.Add(memory, 8)), int(n))); !ok {
		return false
	}
	*slot = ref
	return true
}

